#rotate-hint{
  display:none;
  position:fixed;
  left:50%;
  bottom:16px;
  transform:translateX(-50%);
  z-index:99999;
  max-width:calc(100% - 32px);
  background:var(--bg-deep);
  color:var(--ink);
  border:1px solid var(--line);
  border-radius:14px;
  box-shadow:0 12px 32px rgba(0,0,0,.35);
  align-items:center;
  gap:12px;
  padding:12px 14px;
  font-family:var(--font);
}
#rotate-hint svg{
  flex:none;
  width:26px;height:26px;
  animation:rotate-hint-spin 1.6s ease-in-out infinite;
}
#rotate-hint p{
  margin:0;
  font-size:13px;
  line-height:1.4;
  color:var(--muted);
}
#rotate-hint button{
  flex:none;
  appearance:none;
  border:none;
  background:transparent;
  color:var(--muted);
  font-size:18px;
  line-height:1;
  padding:4px 6px;
  cursor:pointer;
}
